      if (o.domainPriceCents === null) { setPrice(null); setPriceError(null); return; }
      const total = o.domainPriceCents * o.years;
      setPricing(false);
      setPriceError(null);
      setPrice({
        totalCents: total, months: o.years * 12, regularPlanCents: total,
        promoName: "", promoCreditCents: 0,
        couponLabel: null, couponDiscountCents: 0, couponError: null,
        introRenewalMonthly: null,
        renewalTotalCents: total,
        // Domains are excluded from the Creator Partner Program at every tier.
        partnerDiscountCents: 0, partnerDiscountPercent: 0, partnerDiscountTier: "NONE", partnerName: null,
      });
      return;
    }

    /* Hosting and email are quoted by the SERVER too (2026-09-28), exactly like
       VPS and game. They used to be looked up here in a flat per-plan matrix the
       page handed down — which could not know about THIS customer, so the
       Creator Partner Program discount (and anything else per-account) could
       never appear in the total the customer was shown. `quoteHostingOrder` /
       `quoteEmailOrder` return the same `hostingOrderDueCents` /
       `emailOrderDueCents` their order paths charge. */
    const hostingReady = o.service === "hosting" && !!o.hostingPlanId;
    const emailReady = o.service === "email" && !!o.emailPlanId;

    if (!vpsReady && !gameReady && !hostingReady && !emailReady) { setPrice(null); setPriceError(null); return; }

    const mine = ++seq.current;
    setPricing(true);
    const t = setTimeout(async () => {
      if (hostingReady || emailReady) {
        const code = o.couponCode.trim().toUpperCase() || undefined;
        const res = hostingReady
          ? await quoteHostingOrder({ planId: o.hostingPlanId!, termMonths: o.termMonths, couponCode: code })
          : await quoteEmailOrder({ emailPlanId: o.emailPlanId!, termMonths: o.termMonths, couponCode: code });
        if (mine !== seq.current) return;
        setPricing(false);
        if (!res.ok) { setPrice(null); setPriceError(res.error); return; }
        setPriceError(null);
        setPrice({
          totalCents: res.totalCents,
          months: res.months,
          // The full, undiscounted term total — the struck-through "was" price.
          regularPlanCents: res.regularPlanCents,
          promoName: res.promoName,
          promoCreditCents: res.promoCreditCents,
          couponLabel: null, couponDiscountCents: 0, couponError: res.couponError,
          introRenewalMonthly: null,
          renewalTotalCents: res.renewalTotalCents,
          partnerDiscountCents: res.partnerDiscountCents,
          partnerDiscountPercent: res.partnerDiscountPercent,
          partnerDiscountTier: res.partnerDiscountTier,
          partnerName: res.partnerName,
          renewalCardRequired: "renewalCardRequired" in res ? res.renewalCardRequired === true : false,
        });
        return;
      }
      if (gameReady) {
        const res = await quoteGameOrder({
          gamePlanId: o.gamePlanId!,
          termMonths: o.termMonths,
          serverName: o.serverName.trim() || undefined,
          variant: o.gameVariant ?? undefined,
          subdomain: o.subdomain.trim() || undefined,
          config: o.gameConfig,
          couponCode: o.couponCode.trim().toUpperCase() || undefined,
        });
        if (mine !== seq.current) return;
        setPricing(false);
        if (!res.ok) { setPrice(null); setPriceError(res.error); return; }
        setPriceError(null);
        setPrice({
          // chargeCents is already net of couponDiscountCents (gameOrderQuote,
          // lib/game-order.ts) — the same number payAndDeployGame charges.
          totalCents: res.chargeCents,
          months: res.months,
          /* No coupon: chargeCents IS the regular price, nothing to strike
             through. With one: adding the discount back gives the real
             pre-coupon total ("was $X") — algebra on the two authoritative
             numbers the quote already returned, not a second price formula
             (chargeCents = the pre-coupon total - couponDiscountCents, per
             gameOrderQuote). */
          regularPlanCents: res.chargeCents + res.couponDiscountCents,
          promoName: "",
          promoCreditCents: 0,
          couponLabel: res.couponLabel,
          couponDiscountCents: res.couponDiscountCents,
          couponError: res.couponError,
          // `res.monthlyCents` is the tier's RAW regular per-month rate — the
          // exact same basis lib/renewal-charge.ts renews a game server at —
          // so this is only ever populated alongside a genuine intro price
          // (introPercent > 0), never the regular price restated as a warning.
          introRenewalMonthly: res.introPercent > 0 ? res.monthlyCents : null,
          // Flat all-in price — no separate recurring add-ons exist for a game
          // plan (lib/renewal-charge.ts's isGame branch), so chargeCents IS
          // the true renewal amount.
          renewalTotalCents: res.renewalTotalCents,
          partnerDiscountCents: res.partnerDiscountCents,
          partnerDiscountPercent: res.partnerDiscountPercent,
          partnerDiscountTier: res.partnerDiscountTier,
          partnerName: res.partnerName,
        });
        return;
      }

      const res = await quoteOrder({
        planId: o.planId!,
        osTemplateId: o.osId!,
        // `o.hostname` is now always pre-filled by seedOrder — this fallback
        // only matters for a stray render where it's somehow still blank,
        // and even then only feeds a live PRICE preview (never written
        // anywhere), so a fresh random default here is fine.
        hostname: o.hostname.trim() || genDefaultVpsHostname(),
        termMonths: o.termMonths,
        addonBackup: o.addons.includes("backup"),
        /* `orderQuote` (lib/order.ts) prices backup off `backupTier`
           ("FREE"/"PLUS"), NOT off `addonBackup` — that field only feeds
           `autoBackup`/`backupKeep` further down, never the charge. The real
           form submission (DeployView.tsx's hidden `backup_tier` input)
           already gets this right; this live preview call didn't, so
           checking Backup Plus never moved the total shown to the customer
           even though the actual charge at submission was correct. */
        backupTier: o.addons.includes("backup") ? "PLUS" : undefined,
        addonMalware: o.addons.includes("malware"),
        addonDocker: o.addons.includes("docker"),
        dedicatedIp: o.addons.includes("ip"),
        extraDiskGB: o.diskGb,
        couponCode: o.couponCode.trim().toUpperCase() || undefined,
      });
