      setPricing(false);
      if (!res.ok) { setPrice(null); setPriceError(res.error); return; }
      const q = res as QuotedPrice;
      setPriceError(null);
      setPrice({
        totalCents: q.totalCents,
        months: q.months,
        regularPlanCents: q.regularPlanCents,
        promoName: q.promoName,
        promoCreditCents: q.promoCreditCents,
        couponLabel: q.couponLabel,
