/**
 * Pure helpers for the conversion funnel (no DB, no server-only imports, so the
 * browser beacon, the /api/track/deploy-step route, the worker and the tests can
 * all share them).
 *
 * Event vocabulary written to `DeployFunnelEvent` (2026-10-15 conversion pass):
 *
 *   type "step"     a wizard step was reached (one per actor+product+step)
 *   type "error"    a step failed; `errorCode` machine code, `detail.reason` a coarse class
 *   type "complete" the deploy succeeded (server-side, session-stamped)
 *   type "select"   which game/plan/term/region was clicked (unchanged)
 *   type "payment"  one payment-step fact. `errorCode` is a PaymentOutcome below,
 *                   `detail` a sanitised JSON blob (method, plan, term, total, ...)
 *   type "dwell"    milliseconds spent on `step` before leaving it (`detail.ms`)
 *
 * No PII: details are whitelisted below; free text never reaches `detail`.
 */

export type DeployProduct = "vps" | "game" | "hosting" | "email";

/** Why a payment attempt ended (or what was shown). Stable machine strings. */
export const PAYMENT_OUTCOMES = [
  "price_shown", // the total the customer saw on the payment step
  "attempt_started", // they pressed pay / opened a PayPal order
  "insufficient_wallet", // the order needs more balance than they hold
  "card_declined", // generic issuer decline
  "card_insufficient_funds", // issuer says insufficient funds
  "card_expired",
  "card_incorrect", // wrong number / cvc / postcode
  "card_processing_error",
  "three_ds_required", // authentication needed (shown, not yet failed)
  "three_ds_failed", // authentication failed or abandoned
  "paypal_cancelled", // closed the PayPal window without approving
  "paypal_error", // PayPal reported an error
  "paypal_unpaid", // approved/returned but capture was not COMPLETED
  "paypal_approved", // approved by the payer, capture requested
  "validation_error", // blocked before payment by a wizard/server validation
  "coupon_applied",
  "coupon_invalid",
  "wallet_topup_started",
  "wallet_topup_completed",
  "succeeded",
  "abandoned", // server sweep: a pending external payment that never finished
  "other_error",
] as const;
export type PaymentOutcome = (typeof PAYMENT_OUTCOMES)[number];

const OUTCOME_SET = new Set<string>(PAYMENT_OUTCOMES);
export function isPaymentOutcome(v: unknown): v is PaymentOutcome {
  return typeof v === "string" && OUTCOME_SET.has(v);
}

/** Outcomes that mean "this attempt did not pay" (drop-off reasons). */
export const FAILURE_OUTCOMES: readonly PaymentOutcome[] = [
  "insufficient_wallet",
  "card_declined",
  "card_insufficient_funds",
  "card_expired",
  "card_incorrect",
  "card_processing_error",
  "three_ds_failed",
  "paypal_cancelled",
  "paypal_error",
  "paypal_unpaid",
  "validation_error",
  "coupon_invalid",
  "abandoned",
  "other_error",
];

/**
 * Map a Stripe.js confirm error (`code`, `decline_code`, `type`) to an outcome.
 * Stripe.js errors carry no PAN or customer data in these three fields.
 */
export function classifyStripeError(e: {
  code?: string | null;
  declineCode?: string | null;
  type?: string | null;
} | null | undefined): PaymentOutcome {
  const code = (e?.code ?? "").toLowerCase();
  const decline = (e?.declineCode ?? "").toLowerCase();
  const c = decline || code;
  if (!c && !e?.type) return "other_error";
  if (c === "insufficient_funds") return "card_insufficient_funds";
  if (c === "expired_card") return "card_expired";
  if (["incorrect_cvc", "invalid_cvc", "incorrect_number", "invalid_number", "incorrect_zip", "invalid_expiry_month",
    "invalid_expiry_year", "invalid_expiry"].includes(c)) return "card_incorrect";
  if (["authentication_required", "payment_intent_authentication_failure", "payment_method_authentication_failure"].includes(c)) {
    return "three_ds_failed";
  }
  if (c === "processing_error") return "card_processing_error";
  if (["card_declined", "generic_decline", "do_not_honor", "lost_card", "stolen_card", "fraudulent", "card_not_supported",
    "currency_not_supported", "transaction_not_allowed", "pickup_card", "restricted_card", "not_permitted",
    "withdrawal_count_limit_exceeded", "card_velocity_exceeded", "call_issuer", "do_not_try_again", "new_account_information_available",
    "try_again_later", "testmode_decline"].includes(c)) return "card_declined";
  if (e?.type === "card_error") return "card_declined";
  if (e?.type === "validation_error") return "card_incorrect";
  return "other_error";
}

/**
 * Coarse reason class for one of OUR order-action error strings (the wizard's
 * `state.error`). Matching is on the fixed phrases lib/order.ts, lib/game-order.ts
 * and lib/actions-hosting.ts throw; anything unknown is "other".
 */
export function classifyOrderError(message: string | null | undefined): PaymentOutcome | "other" {
  const m = (message ?? "").toLowerCase();
  if (!m) return "other";
  if (m.includes("insufficient balance") || m.includes("top up your wallet") || m.includes("not enough balance")) {
    return "insufficient_wallet";
  }
  if (m.includes("coupon") || m.includes("promo code") || m.includes("promo is")) return "coupon_invalid";
  if (m.includes("verify your email") || m.includes("unverified")) return "validation_error";
  if (m.includes("hostname") || m.includes("subdomain") || m.includes("domain") || m.includes("already") || m.includes("taken")
    || m.includes("required") || m.includes("invalid") || m.includes("must ")) return "validation_error";
  return "other";
}

const MAX_STR = 40;
const SAFE_TOKEN = /^[A-Za-z0-9_.:-]{1,64}$/;

function tok(v: unknown): string | null {
  return typeof v === "string" && SAFE_TOKEN.test(v) ? v.slice(0, 64) : null;
}
function int(v: unknown, max: number): number | null {
  const n = typeof v === "number" ? v : Number(v);
  if (!Number.isFinite(n)) return null;
  return Math.max(0, Math.min(max, Math.round(n)));
}

/**
 * Whitelist + type-check a payment/dwell/error detail blob from the browser.
 * Anything not listed is dropped, strings must be short safe tokens, so a client
 * can never smuggle free text (an email, a hostname) into the funnel table.
 */
export function sanitizeFunnelDetail(raw: unknown): Record<string, string | number | boolean> | null {
  let obj: unknown = raw;
  if (typeof raw === "string") {
    try {
      obj = JSON.parse(raw.slice(0, 2000));
    } catch {
      return null;
    }
  }
  if (!obj || typeof obj !== "object" || Array.isArray(obj)) return null;
  const o = obj as Record<string, unknown>;
  const out: Record<string, string | number | boolean> = {};
  for (const k of ["method", "plan", "game", "coupon", "region", "reason", "ref", "field", "stage"]) {
    const t = tok(o[k]);
    if (t) out[k] = t.slice(0, MAX_STR);
  }
  for (const [k, max] of [["termMonths", 120], ["totalCents", 100_000_000], ["walletCents", 100_000_000],
    ["cardDueCents", 100_000_000], ["ms", 6 * 3_600_000], ["regularCents", 100_000_000]] as const) {
    const n = int(o[k], max);
    if (n !== null) out[k] = n;
  }
  for (const k of ["walletUsed", "couponApplied", "couponInvalid"]) {
    if (typeof o[k] === "boolean") out[k] = o[k] as boolean;
  }
  // stripe class fields: stripe codes are snake_case tokens
  for (const k of ["code", "declineCode"]) {
    const t = tok(o[k]);
    if (t) out[k] = t.slice(0, MAX_STR);
  }
  return Object.keys(out).length ? out : null;
}

/** Strip anything email-shaped / long digit runs from a free-text error message. */
export function scrubMessage(msg: string | null | undefined, max = 300): string | null {
  if (!msg) return null;
  const s = msg
    .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, "[email]")
    .replace(/\b\d{9,}\b/g, "[number]")
    .trim()
    .slice(0, max);
  return s || null;
}

/** Stable actor key for one wizard run: session, else visitor, else account. */
export function actorKey(e: { sessionId?: string | null; visitorId?: string | null; userId?: string | null }): string | null {
  return e.sessionId ?? e.visitorId ?? e.userId ?? null;
}

/** Time-on-step is only trusted inside a sane window (ignores backgrounded tabs). */
export const MAX_DWELL_MS = 30 * 60_000;
export function clampDwell(ms: number): number | null {
  if (!Number.isFinite(ms) || ms < 300) return null;
  return Math.min(MAX_DWELL_MS, Math.round(ms));
}

/**
 * Server-side dedupe windows (ms) per event type. A step/complete is one fact per
 * actor+product+step within the window; payment outcomes repeat legitimately (a
 * second decline is a second signal) so only rapid duplicates are collapsed.
 */
export const DEDUPE_WINDOW_MS: Record<string, number> = {
  step: 6 * 3_600_000,
  complete: 10 * 60_000,
  dwell: 6 * 3_600_000,
  payment: 5_000,
};

