const MAX_STR = 40;
const SAFE_TOKEN = /^[A-Za-z0-9_.:-]{1,64}$/;

function tok(v: unknown): string | null {
  return typeof v === "string" && SAFE_TOKEN.test(v) ? v.slice(0, 64) : null;
}
function int(v: unknown, max: number): number | null {
  const n = typeof v === "number" ? v : Number(v);
  if (!Number.isFinite(n)) return null;
  return Math.max(0, Math.min(max, Math.round(n)));
}

/**
 * Whitelist + type-check a payment/dwell/error detail blob from the browser.
 * Anything not listed is dropped, strings must be short safe tokens, so a client
 * can never smuggle free text (an email, a hostname) into the funnel table.
 */
export function sanitizeFunnelDetail(raw: unknown): Record<string, string | number | boolean> | null {
  let obj: unknown = raw;
  if (typeof raw === "string") {
    try {
      obj = JSON.parse(raw.slice(0, 2000));
    } catch {
      return null;
    }
  }
  if (!obj || typeof obj !== "object" || Array.isArray(obj)) return null;
  const o = obj as Record<string, unknown>;
  const out: Record<string, string | number | boolean> = {};
  for (const k of ["method", "plan", "game", "coupon", "region", "reason", "ref", "field", "stage"]) {
    const t = tok(o[k]);
    if (t) out[k] = t.slice(0, MAX_STR);
  }
  for (const [k, max] of [["termMonths", 120], ["totalCents", 100_000_000], ["walletCents", 100_000_000],
    ["cardDueCents", 100_000_000], ["ms", 6 * 3_600_000], ["regularCents", 100_000_000]] as const) {
    const n = int(o[k], max);
    if (n !== null) out[k] = n;
  }
  for (const k of ["walletUsed", "couponApplied", "couponInvalid"]) {
    if (typeof o[k] === "boolean") out[k] = o[k] as boolean;
  }
  // stripe class fields: stripe codes are snake_case tokens
  for (const k of ["code", "declineCode"]) {
    const t = tok(o[k]);
    if (t) out[k] = t.slice(0, MAX_STR);
  }
  return Object.keys(out).length ? out : null;
}

/** Strip anything email-shaped / long digit runs from a free-text error message. */
export function scrubMessage(msg: string | null | undefined, max = 300): string | null {
  if (!msg) return null;
  const s = msg
    .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, "[email]")
    .replace(/\b\d{9,}\b/g, "[number]")
    .trim()
    .slice(0, max);
  return s || null;
}

/** Stable actor key for one wizard run: session, else visitor, else account. */
export function actorKey(e: { sessionId?: string | null; visitorId?: string | null; userId?: string | null }): string | null {
  return e.sessionId ?? e.visitorId ?? e.userId ?? null;
}

/** Time-on-step is only trusted inside a sane window (ignores backgrounded tabs). */
export const MAX_DWELL_MS = 30 * 60_000;
export function clampDwell(ms: number): number | null {
  if (!Number.isFinite(ms) || ms < 300) return null;
  return Math.min(MAX_DWELL_MS, Math.round(ms));
}

/**
 * Server-side dedupe windows (ms) per event type. A step/complete is one fact per
 * actor+product+step within the window; payment outcomes repeat legitimately (a
 * second decline is a second signal) so only rapid duplicates are collapsed.
 */
export const DEDUPE_WINDOW_MS: Record<string, number> = {
  step: 6 * 3_600_000,
  complete: 10 * 60_000,
  dwell: 6 * 3_600_000,
  payment: 5_000,
};

