cd /tank/dev-worktrees/nx-conversion && python3 - <<'EOF'
p='lib/deploy-funnel-client.ts'
s=open(p).read()
old=s[s.index('/**\n * Record that the user REACHED a wizard step.'):s.index('/**\n * Record that a wizard step FAILED')]
new='''/* Time-on-step. The step the customer is on right now, and when they got there.
 * Leaving it (reaching the next step, or closing the tab) sends one "dwell" event
 * carrying the elapsed ms — measured in the browser from visible time only, so a
 * backgrounded tab is not counted as thinking time (the server also clamps it). */
let current: { product: DeployProduct; step: string; stepIndex: number; at: number; hiddenMs: number; hiddenSince: number | null } | null = null;
let dwellListeners = false;

function flushDwell(): void {
  const c = current;
  if (!c) return;
  const hidden = c.hiddenMs + (c.hiddenSince !== null ? Date.now() - c.hiddenSince : 0);
  const ms = Date.now() - c.at - hidden;
  current = null;
  if (ms < 300) return;
  send({ product: c.product, step: c.step, stepIndex: c.stepIndex, type: "dwell", detail: { ms } });
}

function ensureDwellListeners(): void {
  if (dwellListeners || typeof document === "undefined") return;
  dwellListeners = true;
  document.addEventListener("visibilitychange", () => {
    if (!current) return;
    if (document.visibilityState === "hidden") {
      if (current.hiddenSince === null) current.hiddenSince = Date.now();
    } else if (current.hiddenSince !== null) {
      current.hiddenMs += Date.now() - current.hiddenSince;
      current.hiddenSince = null;
    }
  });
  // pagehide fires on tab close/navigation; sendBeacon survives it.
  window.addEventListener("pagehide", flushDwell);
}

/**
 * Record that the user REACHED a wizard step. De-duped per tab-session so a
