/**
 * Sensible, editable defaults for the game wizard's "Server" step.
 *
 * Why this exists (2026-10-15 conversion pass): the step that precedes Region lost
 * 56% of the sessions that reached it (30-day DeployFunnelEvent), and it is the
 * only step with two REQUIRED text fields that start empty — a server name whose
 * "My server" was a placeholder (looked filled in, was not) and, for Minecraft, a
 * globally-unique play address. Next was blocked with a shake and no value to
 * accept. Defaults beat fields (docs/checkout-conversion research): both are now
 * pre-filled and still fully editable; the live availability check still gates
 * the play address, so nothing here can cause a collision.
 *
 * Pure and dependency-free: safe in the client bundle and unit-tested.
 */
import { SUBDOMAIN_RE, RESERVED_SUBDOMAINS } from "@/lib/game-subdomain-rules";

/** "Minecraft server" — the game's own name, never customer data. */
export function defaultServerName(gameName: string | null | undefined): string {
  const n = (gameName ?? "").trim().replace(/\s+/g, " ").slice(0, 40);
  return n ? `${n} server` : "My server";
}

/** True when `name` is exactly a name we would have defaulted (so it is safe to replace). */
export function isDefaultServerName(name: string, gameName: string | null | undefined): boolean {
  const t = name.trim();
  return t === "" || t === defaultServerName(gameName) || t === "My server";
}

const ALPHABET = "abcdefghjkmnpqrstuvwxyz23456789";

/**
 * A valid, usually-free play address: `<game-slug>-<4 chars>`. `rand` returns [0,1)
 * and is injectable for tests. The result always satisfies SUBDOMAIN_RE and is
 * never a reserved word; availability is still checked live by the wizard.
 */
export function suggestSubdomain(gameName: string, rand: () => number = Math.random): string {
  let slug = gameName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 13).replace(/-+$/g, "");
  if (slug.length < 3) slug = "game";
  let suffix = "";
  for (let i = 0; i < 4; i++) suffix += ALPHABET[Math.floor(rand() * ALPHABET.length) % ALPHABET.length];
  const out = `${slug}-${suffix}`;
  return SUBDOMAIN_RE.test(out) && !RESERVED_SUBDOMAINS.has(out) ? out : `game-${suffix}`;
}
