/**
 * Stale external-payment sweeper (PayPal / Coinbase bridge rows).
 *
 * `PendingExternalPayment` rows are created the moment a customer opens a PayPal
 * (or crypto) checkout. Nothing ever closed the ones that were never paid, so
 * the table held PENDING rows up to 46 days old (2026-10-15 audit: 18 PayPal
 * attempts / 4 paid / 10 stale pending / 4 failed). A stale PENDING row is noise
 * for finance and hides real "paid but not fulfilled" cases.
 *
 * Rules (the safety properties the tests pin):
 *  - only rows with status === "PENDING" are ever selected AND the final UPDATE
 *    is conditional on status still being "PENDING" (updateMany), so a webhook
 *    that flips the row to PAID between read and write wins; a PAID row is never
 *    touched.
 *  - a PayPal row whose order the provider reports COMPLETED is NEVER marked
 *    abandoned: the customer paid and fulfilment is behind. It is counted as
 *    `paidUnfulfilled` and logged loudly instead (an operator must look).
 *  - if PayPal cannot be reached for a row it is skipped (retried next run),
 *    never guessed.
 *  - rows without a providerRef (order creation failed before PayPal answered)
 *    cannot have been paid and are abandoned by age alone.
 *  - Coinbase rows are aged out only when their provider status is unknowable
 *    here is NOT assumed: they are left untouched (webhook-only provider).
 *
 * New status value "ABANDONED" is a plain string in the existing `status`
 * column (no schema change).
 */
import { db } from "./db";
import { getSettingInt } from "./settings";

export const ABANDONED_STATUS = "ABANDONED";
export const DEFAULT_ABANDON_HOURS = 24;
const MAX_PER_RUN = 200;

export type StaleRow = {
  id: string;
  provider: string;
  kind: string;
  userId: string;
  amountCents: number;
  providerRef: string | null;
  createdAt: Date;
};

/** What PayPal says about an order, reduced to the facts the decision needs. */
export type ProviderVerdict = "paid" | "unpaid" | "unknown";

/** PayPal order status -> verdict. CREATED/APPROVED/SAVED/VOIDED/PAYER_ACTION_REQUIRED never moved money. */
export function paypalVerdict(status: string | null | undefined): ProviderVerdict {
  const s = (status ?? "").toUpperCase();
  if (s === "COMPLETED") return "paid";
  if (["CREATED", "APPROVED", "SAVED", "VOIDED", "PAYER_ACTION_REQUIRED", "NOT_FOUND"].includes(s)) return "unpaid";
  return "unknown";
}

export type SweepDeps = {
  now?: Date;
  /** Reads a PayPal order's status. Omit/undefined = PayPal not configured (age-only for unreferenced rows only). */
  getPayPalStatus?: ((orderId: string) => Promise<string>) | null;
  /** Called once per row actually abandoned (activity row, funnel fact). Must not throw. */
  onAbandoned?: (row: StaleRow) => Promise<void>;
};

export type SweepResult = {
  considered: number;
  abandoned: number;
  /** Provider says COMPLETED while we still say PENDING: money taken, not fulfilled. */
  paidUnfulfilled: number;
  /** Skipped: provider unreachable / unknown status / no reconciler for a referenced row. */
  skipped: number;
};

export async function sweepStalePendingPayments(staleHours: number, deps: SweepDeps = {}): Promise<SweepResult> {
  const now = deps.now ?? new Date();
  const hours = Math.max(1, Math.floor(staleHours));
  const cutoff = new Date(now.getTime() - hours * 3_600_000);
  const res: SweepResult = { considered: 0, abandoned: 0, paidUnfulfilled: 0, skipped: 0 };

  const rows = (await db.pendingExternalPayment.findMany({
    where: { status: "PENDING", provider: "paypal", createdAt: { lt: cutoff }, updatedAt: { lt: cutoff } },
    select: { id: true, provider: true, kind: true, userId: true, amountCents: true, providerRef: true, createdAt: true },
    orderBy: { createdAt: "asc" },
    take: MAX_PER_RUN,
  })) as StaleRow[];

  for (const row of rows) {
    res.considered++;
    let verdict: ProviderVerdict;
    if (!row.providerRef) {
      verdict = "unpaid"; // never reached PayPal -> cannot have been paid
    } else if (deps.getPayPalStatus) {
      try {
        verdict = paypalVerdict(await deps.getPayPalStatus(row.providerRef));
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        // A 404 from PayPal = order expired/purged: it was never paid.
        verdict = /\b404\b/.test(msg) ? "unpaid" : "unknown";
      }
    } else {
      verdict = "unknown"; // referenced but no reconciler: refuse to guess
    }

    if (verdict === "paid") {
      res.paidUnfulfilled++;
      console.error(`[abandoned-checkout] PayPal reports order for pending ${row.id} COMPLETED but it is still PENDING here — needs fulfilment review`);
      continue;
    }
    if (verdict === "unknown") {
      res.skipped++;
      continue;
    }
    // Conditional write: only if it is STILL pending (a webhook may have just paid it).
    const upd = await db.pendingExternalPayment.updateMany({
      where: { id: row.id, status: "PENDING" },
      data: { status: ABANDONED_STATUS },
    });
    if (upd.count > 0) {
      res.abandoned++;
      try {
        await deps.onAbandoned?.(row);
      } catch {
        /* telemetry only */
      }
    }
  }
  return res;
}

/** Worker entry: reads the retention setting, wires PayPal + telemetry, logs a summary. */
export async function runStalePaymentSweep(): Promise<SweepResult> {
  const hours = await getSettingInt("pending_payment_abandon_hours", DEFAULT_ABANDON_HOURS);
  const { paypalConfigured, getPayPalOrder } = await import("./paypal");
  const { recordPayment } = await import("./payment-events");
  const { insertDeployFunnelEvent, recentFunnelActor } = await import("./deploy-funnel");
  const result = await sweepStalePendingPayments(hours, {
    getPayPalStatus: paypalConfigured() ? async (id) => (await getPayPalOrder(id)).status : null,
    onAbandoned: async (row) => {
      await recordPayment({
        type: "payment.checkout_expired", outcome: "expired", provider: "paypal", userId: row.userId, method: "paypal",
        amountCents: row.amountCents, reference: row.providerRef ?? row.id, dedupeKey: `pending:${row.id}:abandoned`,
        label: `PayPal checkout abandoned unpaid (${(row.amountCents / 100).toFixed(2)} USD)`, data: { kind: row.kind, purpose: kindToPurpose(row.kind) },
      });
      const product = kindToProduct(row.kind);
      if (product) {
        const actor = await recentFunnelActor(row.userId, product);
        await insertDeployFunnelEvent({
          userId: row.userId, sessionId: actor.sessionId, visitorId: actor.visitorId, product, step: "Payment", stepIndex: 0,
          type: "payment", errorCode: "abandoned",
          detail: JSON.stringify({ method: "paypal", totalCents: row.amountCents }),
        });
      }
    },
  });
  if (result.abandoned > 0 || result.paidUnfulfilled > 0) {
    console.log(`[abandoned-checkout] stale sweep: considered ${result.considered}, abandoned ${result.abandoned}, paid-unfulfilled ${result.paidUnfulfilled}, skipped ${result.skipped}`);
  }
  return result;
}

export function kindToProduct(kind: string): "vps" | "game" | "hosting" | "email" | null {
  switch (kind) {
    case "order": return "vps";
    case "gameOrder": return "game";
    case "hostOrder": return "hosting";
    case "emailOrder": return "email";
    default: return null;
  }
}
export function kindToPurpose(kind: string): string {
  switch (kind) {
    case "order": return "vps_order";
    case "gameOrder": return "game_order";
    case "hostOrder": return "hosting_order";
    case "emailOrder": return "email_order";
    default: return "topup";
  }
}
