/**
 * Pure selection logic for the abandoned-checkout reminder (no DB, no mail), so the
 * rules are unit-tested: who is eligible, what is said, and the frequency cap.
 */
export type AbandonedItem = {
  userId: string;
  /** vps_order | game_order | hosting_order | email_order */
  purpose: string;
  amountCents: number | null;
  /** When the checkout was abandoned/expired. */
  at: Date;
};

export type UserFacts = {
  email: string | null;
  verified: boolean;
  name: string | null;
  /** Paid for / completed an order of any kind AFTER the earliest item below. */
  convertedSince: Date | null;
  /** Last abandoned_checkout (or deploy_winback) email actually sent to them. */
  lastReminderAt: Date | null;
  lastWinbackAt: Date | null;
  marketingAllowed: boolean;
};

export type ReminderPlan = {
  userId: string;
  productLabel: string;
  amountCents: number | null;
};

const LABEL: Record<string, string> = {
  vps_order: "VPS",
  game_order: "game server",
  hosting_order: "web hosting",
  email_order: "business email",
};
export const ORDER_PURPOSES = new Set(Object.keys(LABEL));

const DAY = 86_400_000;

export function planReminders(input: {
  items: AbandonedItem[];
  users: Map<string, UserFacts>;
  now: Date;
  cooldownDays: number;
  maxAgeDays: number;
  /** Don't pile on a deploy win-back sent within this many days (default 3). */
  winbackGapDays?: number;
  maxPerRun: number;
}): { send: ReminderPlan[]; skipped: Record<string, number> } {
  const skipped: Record<string, number> = {};
  const skip = (why: string) => { skipped[why] = (skipped[why] ?? 0) + 1; };
  const nowMs = input.now.getTime();
  const oldest = nowMs - input.maxAgeDays * DAY;
  const winbackGap = (input.winbackGapDays ?? 3) * DAY;

  // Newest abandoned order per customer: that is the one worth finishing.
  const latest = new Map<string, AbandonedItem>();
  for (const it of input.items) {
    if (!ORDER_PURPOSES.has(it.purpose)) continue;
    if (it.at.getTime() < oldest) continue;
    const cur = latest.get(it.userId);
    if (!cur || cur.at < it.at) latest.set(it.userId, it);
  }

  const send: ReminderPlan[] = [];
  for (const [userId, it] of latest) {
    if (send.length >= input.maxPerRun) break;
    const u = input.users.get(userId);
    if (!u || !u.email) { skip("no_email"); continue; }
    if (!u.verified) { skip("unverified"); continue; }
    if (!u.marketingAllowed) { skip("opted_out"); continue; }
    // Paid for something since abandoning: the reminder would be wrong/annoying.
    if (u.convertedSince && u.convertedSince >= it.at) { skip("already_converted"); continue; }
    if (u.lastReminderAt && nowMs - u.lastReminderAt.getTime() < input.cooldownDays * DAY) { skip("cooldown"); continue; }
    if (u.lastWinbackAt && nowMs - u.lastWinbackAt.getTime() < winbackGap) { skip("recent_winback"); continue; }
    send.push({ userId, productLabel: LABEL[it.purpose], amountCents: it.amountCents });
  }
  return { send, skipped };
}
