const SEND_GAP_MS = 1200;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export async function abandonedCheckoutSweep(): Promise<void> {
  try {
    await runStalePaymentSweep();
  } catch (e) {
    console.error("[abandoned-checkout] stale sweep failed", e);
  }

  // ===== MASTER KILL-SWITCH for the email =====
  const envOn = process.env.ABANDONED_CHECKOUT_EMAIL_ENABLED === "true";
  if (!envOn && !(await getSettingBool("abandoned_checkout_email_enabled", false))) return;

  const now = new Date();
  const maxAgeDays = await getSettingInt("abandoned_checkout_email_max_age_days", 7);
  const cooldownDays = await getSettingInt("abandoned_checkout_email_cooldown_days", 14);
  const since = new Date(now.getTime() - maxAgeDays * 86_400_000);

  // Sources of "abandoned": our swept PayPal rows + Stripe checkouts that expired unpaid.
  const items: AbandonedItem[] = [];
  const pend = await db.pendingExternalPayment.findMany({
    where: { status: ABANDONED_STATUS, updatedAt: { gte: since } },
    select: { userId: true, kind: true, amountCents: true, updatedAt: true },
    take: 500,
  });
  for (const p of pend) items.push({ userId: p.userId, purpose: kindToPurpose(p.kind), amountCents: p.amountCents, at: p.updatedAt });

  const expired = await db.activityEvent.findMany({
    where: { type: "payment.checkout_expired", provider: "stripe", userId: { not: null }, createdAt: { gte: since } },
    select: { userId: true, amountCents: true, createdAt: true, data: true },
    take: 500,
  });
  for (const ev of expired) {
    const purpose = (ev.data as { purpose?: unknown } | null)?.purpose;
    if (typeof purpose === "string" && ORDER_PURPOSES.has(purpose) && ev.userId) {
      items.push({ userId: ev.userId, purpose, amountCents: ev.amountCents, at: ev.createdAt });
    }
  }
  if (items.length === 0) return;

  const ids = [...new Set(items.map((i) => i.userId))];
  const [users, reminders, winbacks, paidPending, completes] = await Promise.all([
    db.user.findMany({ where: { id: { in: ids } }, select: { id: true, name: true, email: true, emailVerifiedAt: true } }),
    db.emailLog.findMany({ where: { userId: { in: ids }, template: TEMPLATE_TAG, status: "SENT" }, select: { userId: true, createdAt: true }, orderBy: { createdAt: "desc" }, take: 2000 }),
    db.emailLog.findMany({ where: { userId: { in: ids }, template: "deploy_winback", status: "SENT" }, select: { userId: true, createdAt: true }, orderBy: { createdAt: "desc" }, take: 2000 }),
    db.pendingExternalPayment.findMany({ where: { userId: { in: ids }, status: "PAID", updatedAt: { gte: since } }, select: { userId: true, updatedAt: true } }),
    db.deployFunnelEvent.findMany({ where: { userId: { in: ids }, type: "complete", createdAt: { gte: since } }, select: { userId: true, createdAt: true } }),
  ]);

  const facts = new Map<string, UserFacts>();
  const latestBy = (rows: { userId: string | null; createdAt?: Date; updatedAt?: Date }[]) => {
    const m = new Map<string, Date>();
    for (const r of rows) {
      const d = r.createdAt ?? r.updatedAt;
      if (r.userId && d && (!m.get(r.userId) || m.get(r.userId)! < d)) m.set(r.userId, d);
    }
    return m;
  };
  const lastReminder = latestBy(reminders);
  const lastWinback = latestBy(winbacks);
  const converted = latestBy([...paidPending, ...completes]);
  for (const u of users) {
    let allowed = true;
    try { allowed = await mayDeliverTo(u.id, "product_news", "email"); } catch { allowed = true; }
    facts.set(u.id, {
      email: u.email, verified: !!u.emailVerifiedAt, name: u.name,
      convertedSince: converted.get(u.id) ?? null,
      lastReminderAt: lastReminder.get(u.id) ?? null,
      lastWinbackAt: lastWinback.get(u.id) ?? null,
      marketingAllowed: allowed,
    });
  }

  const plan = planReminders({ items, users: facts, now, cooldownDays, maxAgeDays, maxPerRun: MAX_PER_RUN });
  let sent = 0;
  let failed = 0;
  for (const p of plan.send) {
    const u = facts.get(p.userId)!;
    try {
      const unsub = marketingUnsubUrl(p.userId);
      const built = emails.abandonedCheckout({
        name: u.name,
        productLabel: p.productLabel,
        amountLabel: p.amountCents && p.amountCents > 0 ? `$${(p.amountCents / 100).toFixed(2)}` : null,
        resumeUrl: `${appUrl()}/dashboard/deploy?utm_source=email&utm_medium=email&utm_campaign=abandoned_checkout`,
        unsubscribeUrl: unsub,
      });
      const ok = await sendMail({
        to: u.email!, subject: built.subject, html: built.html, template: built.template,
        listUnsubscribeUrl: unsub, userId: p.userId, kind: "product_news",
      });
      if (ok) sent++; else failed++;
    } catch (e) {
      failed++;
      console.error(`[abandoned-checkout] send failed for user ${p.userId}`, e);
    }
    await sleep(SEND_GAP_MS);
  }
  if (sent > 0 || failed > 0) {
    console.log(`[abandoned-checkout] reminders: sent ${sent}, failed ${failed}, skipped ${JSON.stringify(plan.skipped)}`);
  }
}
