/**
 * Conversion dashboard metrics — PURE definitions (no DB), unit-tested in
 * test/conversion-metrics.test.ts. The loader that feeds these is
 * lib/conversion-dashboard.ts; the page is app/admin/conversion/page.tsx.
 *
 * ── Definitions (the numbers on /admin/conversion mean exactly this) ──────────
 * HUMAN VISIT   a `Visit` row with
 *                 isBot = false                    (ingest + worker re-classification, lib/bots/*)
 *                 AND (botKind IS NULL OR botKind = 'human')
 *                 AND webdriver IS NOT TRUE        (navigator.webdriver automation flag)
 *               `isBot` already folds in UA catalogue, datacenter IP, stale browser and
 *               velocity evidence; `botKind` and `webdriver` are re-checked explicitly so a
 *               row that the worker labelled but did not flip is still excluded.
 * ENGAGED HUMAN a human visit with `interacted = true` (a pointer/scroll/key/touch event was
 *               seen before the close beacon). `interacted IS NULL` (old client / no close
 *               beacon) is NOT counted as engaged — it is "unverified human".
 * VISITOR       distinct COALESCE(visitorId, ip) among the visits above (marketing kind).
 * WIZARD ACTOR  distinct COALESCE(sessionId, visitorId, userId) on DeployFunnelEvent, after
 *               dropping actors whose browser session also appears on a non-human Visit.
 * STEP CONVERSION  of the actors that reached step N, the share that also reached step N+1
 *               (last step: the share that completed the deploy).
 * DROP-OFF REASON  per step, distinct actors that logged a failure-class fact there
 *               (type "error" → detail.reason or errorCode; type "payment" → outcome in
 *               FAILURE_OUTCOMES). Actors that left with no logged fact are "no reason logged".
 */
import { FAILURE_OUTCOMES, actorKey } from "./deploy-funnel-core";

export const HUMAN_VISIT_SQL = `"isBot" = false AND ("botKind" IS NULL OR "botKind" = 'human') AND "webdriver" IS NOT TRUE`;
export const NON_HUMAN_VISIT_SQL = `("isBot" = true OR ("botKind" IS NOT NULL AND "botKind" <> 'human') OR "webdriver" IS TRUE)`;

export type VisitFlags = { isBot: boolean; botKind: string | null; webdriver: boolean | null; interacted: boolean | null };

export function isHumanVisit(v: VisitFlags): boolean {
  return !v.isBot && (v.botKind === null || v.botKind === "human") && v.webdriver !== true;
}
export function isEngagedHuman(v: VisitFlags): boolean {
  return isHumanVisit(v) && v.interacted === true;
}

export type FunnelEventRow = {
  product: string;
  step: string;
  stepIndex: number;
  type: string;
  errorCode: string | null;
  detail: string | null;
  sessionId: string | null;
  visitorId: string | null;
  userId: string | null;
};

export type StepStat = {
  step: string;
  order: number;
  reached: number;
  /** Actors that continued to the next step (or completed, on the last step). */
  continued: number;
  conversionToNext: number; // 0..1
  abandoned: number;
  /** reason -> distinct actors */
  reasons: { reason: string; actors: number }[];
  /** Abandoned actors with no failure-class fact logged on this step. */
  noReasonLogged: number;
  medianDwellMs: number | null;
};

export type ProductFunnelStat = {
  product: string;
  started: number;
  completed: number;
  overallConversion: number;
  steps: StepStat[];
  botActorsExcluded: number;
};

const FAILURE_SET = new Set<string>(FAILURE_OUTCOMES);

function parseDetail(d: string | null): Record<string, unknown> {
  if (!d) return {};
  try {
    const o = JSON.parse(d);
    return o && typeof o === "object" ? (o as Record<string, unknown>) : {};
  } catch {
    return {};
  }
}

function median(xs: number[]): number | null {
  if (xs.length === 0) return null;
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : Math.round((s[m - 1] + s[m]) / 2);
}

/**
 * Build one product's funnel. `botSessions` are browser session ids that appear on a
 * non-human Visit; any actor keyed by one is dropped (the funnel is human-only).
 */
export function buildProductFunnel(
  product: string,
  rows: FunnelEventRow[],
  botSessions: ReadonlySet<string>,
): ProductFunnelStat | null {
  const mine = rows.filter((r) => r.product === product);
  if (mine.length === 0) return null;

  const botActors = new Set<string>();
  const ev = mine.filter((r) => {
    const k = actorKey(r);
    if (!k) return false;
    if (r.sessionId && botSessions.has(r.sessionId)) {
      botActors.add(k);
      return false;
    }
    return true;
  });

  // userId completions match step-runs by userId (server-side complete may lack a session).
  const userOf = new Map<string, string>();
  const completedUsers = new Set<string>();
  const completedActors = new Set<string>();
  for (const r of ev) {
    const k = actorKey(r)!;
    if (r.userId && !userOf.has(k)) userOf.set(k, r.userId);
    if (r.type === "complete") {
      completedActors.add(k);
      if (r.userId) completedUsers.add(r.userId);
    }
  }
  const ranCompleted = (k: string) => completedActors.has(k) || (userOf.has(k) && completedUsers.has(userOf.get(k)!));

  type Acc = { order: number; reached: Set<string>; reasons: Map<string, Set<string>>; dwell: number[] };
  const by = new Map<string, Acc>();
  const get = (step: string, idx: number): Acc => {
    let a = by.get(step);
    if (!a) by.set(step, (a = { order: idx, reached: new Set(), reasons: new Map(), dwell: [] }));
    else if (idx < a.order && idx > 0) a.order = idx;
    return a;
  };
  const addReason = (a: Acc, reason: string, k: string) => {
    const s = a.reasons.get(reason) ?? new Set<string>();
    s.add(k);
    a.reasons.set(reason, s);
  };

  for (const r of ev) {
    const k = actorKey(r)!;
    if (r.type === "step") get(r.step, r.stepIndex).reached.add(k);
    else if (r.type === "error") {
      const a = get(r.step, r.stepIndex);
      const d = parseDetail(r.detail);
      const reason = typeof d.reason === "string" && d.reason !== "other" ? d.reason : r.errorCode ?? "error";
      addReason(a, reason, k);
    } else if (r.type === "payment" && r.errorCode && FAILURE_SET.has(r.errorCode)) {
      addReason(get(r.step, r.stepIndex), r.errorCode, k);
    } else if (r.type === "dwell") {
      const ms = Number(parseDetail(r.detail).ms);
      if (Number.isFinite(ms) && ms > 0) get(r.step, r.stepIndex).dwell.push(ms);
    }
  }

  const ordered = [...by.entries()].filter(([, a]) => a.reached.size > 0).sort((x, y) => x[1].order - y[1].order || x[0].localeCompare(y[0]));
  const steps: StepStat[] = ordered.map(([step, a], i) => {
    const next = ordered[i + 1]?.[1];
    const continuedSet = [...a.reached].filter((k) => (next ? next.reached.has(k) : ranCompleted(k)));
    const continued = continuedSet.length;
    const continuedIds = new Set(continuedSet);
    const abandonedIds = [...a.reached].filter((k) => !continuedIds.has(k));
    const reasonRows = [...a.reasons.entries()]
      .map(([reason, set]) => ({ reason, actors: set.size }))
      .sort((p, q) => q.actors - p.actors);
    const explained = new Set<string>();
    for (const set of a.reasons.values()) for (const k of set) explained.add(k);
    return {
      step,
      order: a.order,
      reached: a.reached.size,
      continued,
      conversionToNext: a.reached.size ? continued / a.reached.size : 0,
      abandoned: abandonedIds.length,
      reasons: reasonRows,
      noReasonLogged: abandonedIds.filter((k) => !explained.has(k)).length,
      medianDwellMs: median(a.dwell),
    };
  });

  const started = steps[0]?.reached ?? 0;
  const completed = new Set([...completedActors, ...[...completedUsers].map((u) => `u:${u}`)]).size
    ? completedUsers.size + [...completedActors].filter((k) => !userOf.has(k) || !completedUsers.has(userOf.get(k)!)).length
    : 0;
  return {
    product,
    started,
    completed,
    overallConversion: started ? Math.min(1, completed / started) : 0,
    steps,
    botActorsExcluded: botActors.size,
  };
}

// ---- payments ---------------------------------------------------------------

export type PaymentGroupRow = { provider: string | null; outcome: string | null; n: number; cents: number };
export type MethodStat = {
  provider: string;
  succeeded: number;
  failed: number;
  needsAction: number; // 3-D Secure / authentication
  abandoned: number; // cancelled | expired
  pending: number;
  paidCents: number;
  failedCents: number;
  successRate: number | null; // succeeded / (succeeded + failed + abandoned), null when no attempts
};

const PROVIDER_ORDER = ["stripe", "paypal", "wallet", "coinbase"];

export function summarisePayments(rows: PaymentGroupRow[]): MethodStat[] {
  const m = new Map<string, MethodStat>();
  for (const r of rows) {
    const p = r.provider ?? "other";
    const s = m.get(p) ?? { provider: p, succeeded: 0, failed: 0, needsAction: 0, abandoned: 0, pending: 0, paidCents: 0, failedCents: 0, successRate: null };
    switch (r.outcome) {
      case "succeeded": s.succeeded += r.n; s.paidCents += r.cents; break;
      case "failed": s.failed += r.n; s.failedCents += r.cents; break;
      case "requires_action": s.needsAction += r.n; break;
      case "cancelled": case "expired": s.abandoned += r.n; s.failedCents += r.cents; break;
      case "pending": s.pending += r.n; break;
      default: break; // opened / refunded / disputed are not attempt outcomes
    }
    m.set(p, s);
  }
  const out = [...m.values()];
  for (const s of out) {
    const attempts = s.succeeded + s.failed + s.abandoned;
    s.successRate = attempts > 0 ? s.succeeded / attempts : null;
  }
  return out.sort((a, b) => (PROVIDER_ORDER.indexOf(a.provider) + 99) % 99 - (PROVIDER_ORDER.indexOf(b.provider) + 99) % 99);
}

