cd /tank/dev-worktrees/nx-conversion && cat > lib/conversion-dashboard.ts <<'EOF'
import { db } from "@/lib/db";
import {
  HUMAN_VISIT_SQL,
  NON_HUMAN_VISIT_SQL,
  buildProductFunnel,
  summarisePayments,
  type FunnelEventRow,
  type MethodStat,
  type ProductFunnelStat,
} from "@/lib/conversion-metrics";

/**
 * Data for /admin/conversion. Read-only, window-scoped, aggregate-only (no customer
 * identifiers leave this module). Definitions: lib/conversion-metrics.ts header.
 */
const DAY = 86_400_000;
const EVENT_CAP = 150_000;
const PRODUCTS = ["game", "vps", "hosting", "email"] as const;

export type TrafficStats = {
  /** All distinct visitors (marketing kind), bots included. */
  rawVisitors: number;
  /** Distinct visitors with at least one human visit. */
  humanVisitors: number;
  /** Of those, with `interacted = true` on a human visit. */
  engagedVisitors: number;
  /** Distinct visitors with ONLY non-human visits (excluded). */
  botVisitors: number;
  /** Excluded because Visit.webdriver = true (subset of botVisitors, shown for transparency). */
  webdriverVisitors: number;
  daily: { day: string; human: number; raw: number }[];
};

export type PaymentsStats = {
  methods: MethodStat[];
  /** Sum of amount on checkouts left unpaid: PendingExternalPayment ABANDONED/stale PENDING + Stripe checkouts expired. */
  abandonedCents: number;
  abandonedCount: number;
  stalePendingCount: number;
  walletDebitCount: number;
  walletDebitCents: number;
  topupStarted: number;
  topupCompleted: number;
};

export type ConversionData = {
  days: number;
  generatedAt: string;
  traffic: TrafficStats;
  signups: { total: number; verified: number };
  funnels: ProductFunnelStat[];
  payments: PaymentsStats;
  /** True when the DeployFunnelEvent read failed (table/columns missing on this DB). */
  funnelUnavailable: boolean;
};

async function trafficStats(since: Date): Promise<TrafficStats> {
  type T = { raw: bigint; human: bigint; engaged: bigint; webdriver: bigint };
  const [t] = await db.$queryRawUnsafe<T[]>(
    `WITH v AS (
       SELECT COALESCE("visitorId", "ip") AS vid,
              bool_or(${HUMAN_VISIT_SQL}) AS human,
              bool_or(${HUMAN_VISIT_SQL} AND "interacted" IS TRUE) AS engaged,
              bool_or("webdriver" IS TRUE) AS wd
         FROM "Visit"
        WHERE "createdAt" >= $1 AND "kind" = 'marketing'
        GROUP BY 1)
     SELECT COUNT(*) AS raw,
            COUNT(*) FILTER (WHERE human) AS human,
            COUNT(*) FILTER (WHERE engaged) AS engaged,
            COUNT(*) FILTER (WHERE wd AND NOT human) AS webdriver
       FROM v`,
    since,
  );
  type D = { day: Date; human: bigint; raw: bigint }[];
  const daily = await db.$queryRawUnsafe<D>(
    `SELECT date_trunc('day', "createdAt") AS day,
            COUNT(DISTINCT COALESCE("visitorId", "ip")) FILTER (WHERE ${HUMAN_VISIT_SQL}) AS human,
            COUNT(DISTINCT COALESCE("visitorId", "ip")) AS raw
       FROM "Visit"
      WHERE "createdAt" >= $1 AND "kind" = 'marketing'
      GROUP BY 1 ORDER BY 1`,
    since,
  );
  const raw = Number(t?.raw ?? 0);
  const human = Number(t?.human ?? 0);
  return {
    rawVisitors: raw,
    humanVisitors: human,
    engagedVisitors: Number(t?.engaged ?? 0),
    botVisitors: Math.max(0, raw - human),
    webdriverVisitors: Number(t?.webdriver ?? 0),
    daily: daily.map((d) => ({ day: d.day.toISOString().slice(0, 10), human: Number(d.human), raw: Number(d.raw) })),
  };
}

async function botSessionIds(since: Date): Promise<Set<string>> {
  const rows = await db.$queryRawUnsafe<{ sid: string }[]>(
    `SELECT DISTINCT "sessionId" AS sid FROM "Visit"
      WHERE "createdAt" >= $1 AND "sessionId" IS NOT NULL AND ${NON_HUMAN_VISIT_SQL}`,
    since,
  );
  return new Set(rows.map((r) => r.sid));
}

async function loadFunnels(since: Date): Promise<{ funnels: ProductFunnelStat[]; unavailable: boolean }> {
  try {
    const rows = await db.$queryRawUnsafe<FunnelEventRow[]>(
      `SELECT "product", "step", "stepIndex", "type", "errorCode", "detail", "sessionId", "visitorId", "userId"
         FROM "DeployFunnelEvent"
        WHERE "createdAt" >= $1 AND "type" IN ('step','error','complete','payment','dwell')
        ORDER BY "createdAt" DESC
        LIMIT ${EVENT_CAP}`,
      since,
    );
    const bots = await botSessionIds(since);
    const funnels = PRODUCTS.map((p) => buildProductFunnel(p, rows, bots)).filter((f): f is ProductFunnelStat => f !== null);
    return { funnels, unavailable: false };
  } catch {
    return { funnels: [], unavailable: true };
  }
}

async function paymentsStats(since: Date): Promise<PaymentsStats> {
  const grouped = await db.activityEvent.groupBy({
    by: ["provider", "outcome"],
    where: { category: "payment", createdAt: { gte: since }, outcome: { not: null } },
    _count: { _all: true },
    _sum: { amountCents: true },
  });
  const methods = summarisePayments(
    grouped.map((g) => ({ provider: g.provider, outcome: g.outcome, n: g._count._all, cents: g._sum.amountCents ?? 0 })),
  );

  const [abandonedRows, staleRows, stripeExpired, debits, topupOpened, topupPaid] = await Promise.all([
    db.pendingExternalPayment.aggregate({ where: { status: "ABANDONED", updatedAt: { gte: since } }, _count: { _all: true }, _sum: { amountCents: true } }),
    db.pendingExternalPayment.aggregate({ where: { status: "PENDING", createdAt: { lt: new Date(Date.now() - DAY) } }, _count: { _all: true }, _sum: { amountCents: true } }),
    db.activityEvent.aggregate({ where: { type: "payment.checkout_expired", provider: "stripe", createdAt: { gte: since } }, _count: { _all: true }, _sum: { amountCents: true } }),
    db.walletTransaction.aggregate({ where: { amountCents: { lt: 0 }, createdAt: { gte: since } }, _count: { _all: true }, _sum: { amountCents: true } }),
    db.$queryRawUnsafe<{ n: bigint }[]>(
      `SELECT COUNT(*) AS n FROM "ActivityEvent" WHERE "type" = 'payment.checkout_opened' AND "createdAt" >= $1 AND "data"->>'purpose' = 'topup'`, since),
    db.$queryRawUnsafe<{ n: bigint }[]>(
      `SELECT COUNT(*) AS n FROM "ActivityEvent" WHERE "type" = 'payment.succeeded' AND "createdAt" >= $1 AND "data"->>'purpose' = 'topup'`, since),
  ]);

  return {
    methods,
    abandonedCents: (abandonedRows._sum.amountCents ?? 0) + (staleRows._sum.amountCents ?? 0) + (stripeExpired._sum.amountCents ?? 0),
    abandonedCount: abandonedRows._count._all + staleRows._count._all + stripeExpired._count._all,
    stalePendingCount: staleRows._count._all,
    walletDebitCount: debits._count._all,
    walletDebitCents: Math.abs(debits._sum.amountCents ?? 0),
    topupStarted: Number(topupOpened[0]?.n ?? 0),
    topupCompleted: Number(topupPaid[0]?.n ?? 0),
  };
}

export async function loadConversion(days: number): Promise<ConversionData> {
  const since = new Date(Date.now() - days * DAY);
  const [traffic, signupsTotal, signupsVerified, fun, payments] = await Promise.all([
    trafficStats(since),
    db.user.count({ where: { createdAt: { gte: since } } }),
    db.user.count({ where: { createdAt: { gte: since }, emailVerifiedAt: { not: null } } }),
    loadFunnels(since),
    paymentsStats(since),
  ]);
  return {
    days,
    generatedAt: new Date().toISOString(),
    traffic,
    signups: { total: signupsTotal, verified: signupsVerified },
    funnels: fun.funnels,
    payments,
    funnelUnavailable: fun.unavailable,
  };
}
