      `SELECT "product", "step", "stepIndex", "type", "errorCode", "detail", "sessionId", "visitorId", "userId"
         FROM "DeployFunnelEvent"
        WHERE "createdAt" >= $1 AND "type" IN ('step','error','complete','payment','dwell')
        ORDER BY "createdAt" DESC
        LIMIT ${EVENT_CAP}`,
      since,
    );
    const bots = await botSessionIds(since);
    const funnels = PRODUCTS.map((p) => buildProductFunnel(p, rows, bots)).filter((f): f is ProductFunnelStat => f !== null);
    return { funnels, unavailable: false };
  } catch {
    return { funnels: [], unavailable: true };
  }
}

async function paymentsStats(since: Date): Promise<PaymentsStats> {
  const grouped = await db.activityEvent.groupBy({
    by: ["provider", "outcome"],
    where: { category: "payment", createdAt: { gte: since }, outcome: { not: null } },
    _count: { _all: true },
    _sum: { amountCents: true },
  });
  const methods = summarisePayments(
    grouped.map((g) => ({ provider: g.provider, outcome: g.outcome, n: g._count._all, cents: g._sum.amountCents ?? 0 })),
  );

  const [abandonedRows, staleRows, stripeExpired, debits, topupOpened, topupPaid] = await Promise.all([
    db.pendingExternalPayment.aggregate({ where: { status: "ABANDONED", updatedAt: { gte: since } }, _count: { _all: true }, _sum: { amountCents: true } }),
    db.pendingExternalPayment.aggregate({ where: { status: "PENDING", createdAt: { lt: new Date(Date.now() - DAY) } }, _count: { _all: true }, _sum: { amountCents: true } }),
    db.activityEvent.aggregate({ where: { type: "payment.checkout_expired", provider: "stripe", createdAt: { gte: since } }, _count: { _all: true }, _sum: { amountCents: true } }),
    db.walletTransaction.aggregate({ where: { amountCents: { lt: 0 }, createdAt: { gte: since } }, _count: { _all: true }, _sum: { amountCents: true } }),
    db.$queryRawUnsafe<{ n: bigint }[]>(
      `SELECT COUNT(*) AS n FROM "ActivityEvent" WHERE "type" = 'payment.checkout_opened' AND "createdAt" >= $1 AND "data"->>'purpose' = 'topup'`, since),
    db.$queryRawUnsafe<{ n: bigint }[]>(
      `SELECT COUNT(*) AS n FROM "ActivityEvent" WHERE "type" = 'payment.succeeded' AND "createdAt" >= $1 AND "data"->>'purpose' = 'topup'`, since),
  ]);

  return {
    methods,
    abandonedCents: (abandonedRows._sum.amountCents ?? 0) + (staleRows._sum.amountCents ?? 0) + (stripeExpired._sum.amountCents ?? 0),
    abandonedCount: abandonedRows._count._all + staleRows._count._all + stripeExpired._count._all,
    stalePendingCount: staleRows._count._all,
    walletDebitCount: debits._count._all,
    walletDebitCents: Math.abs(debits._sum.amountCents ?? 0),
    topupStarted: Number(topupOpened[0]?.n ?? 0),
    topupCompleted: Number(topupPaid[0]?.n ?? 0),
  };
}

export async function loadConversion(days: number): Promise<ConversionData> {
  const since = new Date(Date.now() - days * DAY);
  const [traffic, signupsTotal, signupsVerified, fun, payments] = await Promise.all([
    trafficStats(since),
    db.user.count({ where: { createdAt: { gte: since } } }),
    db.user.count({ where: { createdAt: { gte: since }, emailVerifiedAt: { not: null } } }),
    loadFunnels(since),
    paymentsStats(since),
  ]);
  return {
    days,
    generatedAt: new Date().toISOString(),
    traffic,
    signups: { total: signupsTotal, verified: signupsVerified },
    funnels: fun.funnels,
    payments,
    funnelUnavailable: fun.unavailable,
  };
}
