import type { StepStat } from "@/lib/conversion-metrics";

/**
 * Dependency-free horizontal funnel: one bar per step, width = actors that reached
 * it, with the step -> next conversion printed at the right edge. Server-safe.
 */
export function FunnelSvg({ steps, completed }: { steps: StepStat[]; completed: number }) {
  const rows = [
    ...steps.map((s) => ({ label: s.step, n: s.reached, conv: s.conversionToNext as number | null, tone: "#8a70fb" })),
    { label: "Complete", n: completed, conv: null as number | null, tone: "#34d399" },
  ];
  const max = Math.max(...rows.map((r) => r.n), 1);
  const rowH = 30;
  const w = 720;
  const labelW = 120;
  const barW = w - labelW - 120;
  const h = rows.length * rowH + 4;
  return (
    <svg viewBox={`0 0 ${w} ${h}`} width="100%" role="img" aria-label="Wizard funnel: actors reaching each step" style={{ maxHeight: h }}>
      {rows.map((r, i) => {
        const y = i * rowH + 2;
        const bw = Math.max(r.n > 0 ? 2 : 0, (r.n / max) * barW);
        return (
          <g key={`${r.label}-${i}`}>
            <text x={0} y={y + 18} fontSize="12" fill="#cbd5e1">{r.label}</text>
            <rect x={labelW} y={y + 4} width={barW} height={18} rx={4} fill="rgba(255,255,255,0.06)" />
            <rect x={labelW} y={y + 4} width={bw} height={18} rx={4} fill={r.tone} />
            <text x={labelW + 6} y={y + 18} fontSize="11" fill="#fff" fontWeight="600">{r.n.toLocaleString()}</text>
            {r.conv !== null && (
              <text x={w} y={y + 18} fontSize="11" textAnchor="end" fill={r.conv < 0.5 ? "#f87171" : "#94a3b8"}>
                {(r.conv * 100).toFixed(0)}% continue
              </text>
            )}
          </g>
        );
      })}
    </svg>
  );
}
