                                ))}
                                {s.noReasonLogged > 0 && <span style={{ color: "var(--adm-muted)" }}>No reason logged <b className="tabular-nums">{s.noReasonLogged}</b></span>}
                              </span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </Panel>
          ))}
        </div>
      )}

      <h2 className="mb-3 mt-8 text-[15px] font-semibold">Payments by method</h2>
      <Panel>
        {pay.methods.length === 0 ? <EmptyRow>No payment records in this window.</EmptyRow> : (
          <div className="overflow-x-auto p-4">
            <table className="w-full text-left text-[12.5px]">
              <thead style={{ color: "var(--adm-muted)" }}>
                <tr><th className="py-1 pr-3">Method</th><th className="pr-3">Succeeded</th><th className="pr-3">Failed</th><th className="pr-3">3DS needed</th><th className="pr-3">Abandoned</th><th className="pr-3">Success rate</th><th className="pr-3">Paid</th><th>Lost</th></tr>
              </thead>
              <tbody>
                {pay.methods.map((m) => (
                  <tr key={m.provider} className="border-t border-white/[0.06]">
                    <td className="py-1.5 pr-3 font-medium">{PROVIDER_LABEL[m.provider] ?? m.provider}</td>
                    <td className="pr-3 tabular-nums">{m.succeeded}</td>
                    <td className="pr-3 tabular-nums">{m.failed}</td>
                    <td className="pr-3 tabular-nums">{m.needsAction}</td>
                    <td className="pr-3 tabular-nums">{m.abandoned}</td>
                    <td className="pr-3 tabular-nums" style={{ minWidth: 110 }}>
                      {m.successRate === null ? "—" : (<><span>{(m.successRate * 100).toFixed(0)}%</span><MeterBar value={m.successRate * 100} max={100} color="#34d399" className="mt-1" /></>)}
                    </td>
                    <td className="pr-3 tabular-nums">{usd(m.paidCents)}</td>
                    <td className="tabular-nums">{usd(m.failedCents)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            <p className="mt-3 text-xs" style={{ color: "var(--adm-muted)" }}>
              Source: payment records (ActivityEvent category payment). Wallet-paid orders are not written there; in this window the wallet was
              debited {pay.walletDebitCount.toLocaleString()} times for {usd(pay.walletDebitCents)} (all debits, renewals included). Wallet top-ups:
              {" "}{pay.topupStarted} checkouts opened, {pay.topupCompleted} completed. Card, 3-D Secure, validation and wallet-short reasons are in
              the funnel table above.
            </p>
          </div>
        )}
      </Panel>
    </div>
  );
}
