cd /tank/dev-worktrees/nx-conversion && cat > test/conversion-funnel.test.ts <<'EOF'
import "./_cyrus-server-only-shim";
import { test } from "node:test";
import assert from "node:assert/strict";

type Row = Record<string, unknown>;
const pending: Row[] = [];
(globalThis as unknown as { prisma: unknown }).prisma = {
  pendingExternalPayment: {
    async findMany({ where }: { where: { status: string; provider: string; createdAt: { lt: Date } } }) {
      return pending.filter((r) => r.status === where.status && r.provider === where.provider && (r.createdAt as Date) < where.createdAt.lt);
    },
    async updateMany({ where, data }: { where: { id: string; status: string }; data: { status: string } }) {
      const r = pending.find((x) => x.id === where.id && x.status === where.status);
      if (!r) return { count: 0 };
      r.status = data.status;
      return { count: 1 };
    },
  },
};

import {
  classifyStripeError, classifyOrderError, sanitizeFunnelDetail, scrubMessage, clampDwell, isPaymentOutcome,
} from "../lib/deploy-funnel-core";
import { buildProductFunnel, summarisePayments, isHumanVisit, isEngagedHuman, type FunnelEventRow } from "../lib/conversion-metrics";
import { planReminders, type UserFacts } from "../lib/abandoned-checkout-plan";
import { sweepStalePendingPayments, paypalVerdict } from "../lib/abandoned-checkout";
import { defaultServerName, isDefaultServerName, suggestSubdomain } from "../lib/nx/server-defaults";
import { SUBDOMAIN_RE, RESERVED_SUBDOMAINS } from "../lib/game-subdomain-rules";
import { SAMPLES, SAMPLE_UNSUB } from "../lib/email-samples";

test("stripe errors classify by code/decline_code, never by message", () => {
  assert.equal(classifyStripeError({ code: "card_declined", declineCode: "insufficient_funds" }), "card_insufficient_funds");
  assert.equal(classifyStripeError({ code: "card_declined", declineCode: "generic_decline" }), "card_declined");
  assert.equal(classifyStripeError({ code: "expired_card" }), "card_expired");
  assert.equal(classifyStripeError({ code: "incorrect_cvc" }), "card_incorrect");
  assert.equal(classifyStripeError({ code: "payment_intent_authentication_failure" }), "three_ds_failed");
  assert.equal(classifyStripeError({ type: "card_error" }), "card_declined");
  assert.equal(classifyStripeError(null), "other_error");
});

test("order refusals classify by our own phrases", () => {
  assert.equal(classifyOrderError("Insufficient balance. Top up your wallet first."), "insufficient_wallet");
  assert.equal(classifyOrderError("That subdomain is already taken"), "validation_error");
  assert.equal(classifyOrderError("Something odd"), "other");
});

test("funnel detail is whitelisted: free text and unknown keys never survive", () => {
  const d = sanitizeFunnelDetail({ method: "paypal", totalCents: 1200, email: "a@b.co", note: "hello world", plan: "plan_1", walletUsed: true, ms: "999999999999" });
  assert.deepEqual(d, { method: "paypal", plan: "plan_1", totalCents: 1200, ms: 6 * 3_600_000, walletUsed: true });
  assert.equal(sanitizeFunnelDetail({ method: "has space@x.com" }), null);
  assert.equal(sanitizeFunnelDetail("not json"), null);
  assert.equal(scrubMessage("bad for jo@example.com 123456789012"), "bad for [email] [number]");
  assert.equal(clampDwell(100), null);
  assert.equal(clampDwell(9e9), 30 * 60_000);
  assert.ok(isPaymentOutcome("paypal_cancelled") && !isPaymentOutcome("drop table"));
});

const ev = (p: Partial<FunnelEventRow>): FunnelEventRow => ({
  product: "game", step: "Game", stepIndex: 0, type: "step", errorCode: null, detail: null,
  sessionId: null, visitorId: null, userId: null, ...p,
});

test("funnel: step conversion, reasons, dwell, bot sessions dropped, completion matched by user", () => {
  const rows: FunnelEventRow[] = [];
  for (const s of ["s1", "s2", "s3", "bot1"]) rows.push(ev({ sessionId: s, step: "Game", stepIndex: 1 }));
  for (const s of ["s1", "s2", "bot1"]) rows.push(ev({ sessionId: s, step: "Server", stepIndex: 2 }));
  rows.push(ev({ sessionId: "s1", step: "Payment", stepIndex: 4, userId: "u1" }));
  rows.push(ev({ sessionId: "s1", step: "Payment", stepIndex: 4, userId: "u1", type: "payment", errorCode: "card_declined" }));
  rows.push(ev({ sessionId: "s2", step: "Server", stepIndex: 2, type: "payment", errorCode: "validation_error" }));
  rows.push(ev({ sessionId: "s1", step: "Server", stepIndex: 2, type: "dwell", detail: JSON.stringify({ ms: 4000 }) }));
  rows.push(ev({ sessionId: "s1", step: "Server", stepIndex: 2, type: "dwell", detail: JSON.stringify({ ms: 8000 }) }));
  // server-side completion: only userId + (stamped) session
  rows.push(ev({ sessionId: "s1", userId: "u1", type: "complete", step: "Complete", stepIndex: 5 }));
  const f = buildProductFunnel("game", rows, new Set(["bot1"]))!;
  assert.equal(f.botActorsExcluded, 1);
  assert.equal(f.started, 3);
  assert.equal(f.completed, 1);
  const game = f.steps.find((s) => s.step === "Game")!;
  assert.equal(game.reached, 3);
  assert.equal(game.continued, 2);
  assert.ok(Math.abs(game.conversionToNext - 2 / 3) < 1e-9);
  const server = f.steps.find((s) => s.step === "Server")!;
  assert.equal(server.reached, 2);
  assert.equal(server.continued, 1); // only s1 reaches Payment
  assert.deepEqual(server.reasons, [{ reason: "validation_error", actors: 1 }]);
  assert.equal(server.noReasonLogged, 0); // s2 left with a logged reason
  assert.equal(server.medianDwellMs, 6000);
  const pay = f.steps.find((s) => s.step === "Payment")!;
  assert.equal(pay.continued, 1); // completed
  assert.deepEqual(pay.reasons, [{ reason: "card_declined", actors: 1 }]);
});

test("events with no actor key are never counted", () => {
  const f = buildProductFunnel("game", [ev({ step: "Game" })], new Set());
  assert.equal(f, null);
});

test("payments summary: success rate excludes opened/refunded, abandoned counts as a loss", () => {
  const s = summarisePayments([
    { provider: "paypal", outcome: "succeeded", n: 4, cents: 4000 },
    { provider: "paypal", outcome: "failed", n: 4, cents: 71200 },
    { provider: "paypal", outcome: "expired", n: 10, cents: 5000 },
    { provider: "paypal", outcome: "opened", n: 18, cents: 0 },
    { provider: "stripe", outcome: "succeeded", n: 9, cents: 9000 },
  ]);
  const pp = s.find((x) => x.provider === "paypal")!;
  assert.equal(pp.successRate, 4 / 18);
  assert.equal(pp.failedCents, 76200);
  assert.equal(s[0].provider, "stripe");
});

test("human visit definition", () => {
  const base = { isBot: false, botKind: null, webdriver: null, interacted: null };
  assert.ok(isHumanVisit(base));
  assert.ok(!isHumanVisit({ ...base, isBot: true }));
  assert.ok(!isHumanVisit({ ...base, botKind: "scraper" }));
  assert.ok(isHumanVisit({ ...base, botKind: "human" }));
  assert.ok(!isHumanVisit({ ...base, webdriver: true }));
  assert.ok(!isEngagedHuman(base));
  assert.ok(isEngagedHuman({ ...base, interacted: true }));
});

test("PayPal verdicts", () => {
  assert.equal(paypalVerdict("COMPLETED"), "paid");
  assert.equal(paypalVerdict("CREATED"), "unpaid");
  assert.equal(paypalVerdict("APPROVED"), "unpaid");
  assert.equal(paypalVerdict("WHATEVER"), "unknown");
});

test("stale sweep: abandons unpaid, never a COMPLETED order, never a PAID row, skips on API error", async () => {
  const old = new Date(Date.now() - 46 * 86_400_000);
  const mk = (id: string, status: string, ref: string | null) => ({ id, provider: "paypal", kind: "gameOrder", userId: "u", amountCents: 1000, providerRef: ref, status, createdAt: old, updatedAt: old });
  pending.length = 0;
  pending.push(mk("a", "PENDING", "O-CREATED"), mk("b", "PENDING", "O-DONE"), mk("c", "PAID", "O-PAID"), mk("d", "PENDING", "O-ERR"), mk("e", "PENDING", null), mk("f", "PENDING", "O-404"));
  const seen: string[] = [];
  const r = await sweepStalePendingPayments(24, {
    getPayPalStatus: async (id) => {
      if (id === "O-CREATED") return "CREATED";
      if (id === "O-DONE") return "COMPLETED";
      if (id === "O-404") throw new Error("PayPal API /v2/checkout/orders/x failed: 404 {}");
      throw new Error("timeout");
    },
    onAbandoned: async (row) => { seen.push(row.id); },
  });
  const st = Object.fromEntries(pending.map((p) => [p.id, p.status]));
  assert.deepEqual(st, { a: "ABANDONED", b: "PENDING", c: "PAID", d: "PENDING", e: "ABANDONED", f: "ABANDONED" });
  assert.deepEqual(seen.sort(), ["a", "e", "f"]);
  assert.equal(r.paidUnfulfilled, 1);
  assert.equal(r.skipped, 1);
  assert.equal(r.abandoned, 3);
});

test("stale sweep: without a PayPal reconciler a referenced row is left alone", async () => {
  const old = new Date(Date.now() - 5 * 86_400_000);
  pending.length = 0;
  pending.push({ id: "x", provider: "paypal", kind: "order", userId: "u", amountCents: 5, providerRef: "O-1", status: "PENDING", createdAt: old, updatedAt: old });
  const r = await sweepStalePendingPayments(24, { getPayPalStatus: null });
  assert.equal(pending[0].status, "PENDING");
  assert.equal(r.skipped, 1);
});

test("a row created inside the window is not touched", async () => {
  const fresh = new Date(Date.now() - 3 * 3_600_000);
  pending.length = 0;
  pending.push({ id: "n", provider: "paypal", kind: "order", userId: "u", amountCents: 5, providerRef: null, status: "PENDING", createdAt: fresh, updatedAt: fresh });
  await sweepStalePendingPayments(24, {});
  assert.equal(pending[0].status, "PENDING");
});

test("abandoned-checkout reminder plan: eligibility, cooldown, one per customer", () => {
  const now = new Date("2026-10-15T12:00:00Z");
  const hoursAgo = (h: number) => new Date(now.getTime() - h * 3_600_000);
  const ok: UserFacts = { email: "x@y.z", verified: true, name: "A", convertedSince: null, lastReminderAt: null, lastWinbackAt: null, marketingAllowed: true };
  const users = new Map<string, UserFacts>([
    ["ok", ok],
    ["unverified", { ...ok, verified: false }],
    ["optout", { ...ok, marketingAllowed: false }],
    ["paid", { ...ok, convertedSince: hoursAgo(1) }],
    ["cool", { ...ok, lastReminderAt: hoursAgo(24 * 3) }],
    ["wb", { ...ok, lastWinbackAt: hoursAgo(24) }],
    ["old", ok],
    ["topup", ok],
  ]);
  const items = [
    { userId: "ok", purpose: "game_order", amountCents: 1200, at: hoursAgo(30) },
    { userId: "ok", purpose: "vps_order", amountCents: 900, at: hoursAgo(26) }, // newest wins
    { userId: "unverified", purpose: "vps_order", amountCents: 1, at: hoursAgo(30) },
    { userId: "optout", purpose: "vps_order", amountCents: 1, at: hoursAgo(30) },
    { userId: "paid", purpose: "vps_order", amountCents: 1, at: hoursAgo(30) },
    { userId: "cool", purpose: "vps_order", amountCents: 1, at: hoursAgo(30) },
    { userId: "wb", purpose: "vps_order", amountCents: 1, at: hoursAgo(30) },
    { userId: "old", purpose: "vps_order", amountCents: 1, at: hoursAgo(24 * 20) },
    { userId: "topup", purpose: "topup", amountCents: 1, at: hoursAgo(30) },
  ];
  const p = planReminders({ items, users, now, cooldownDays: 14, maxAgeDays: 7, maxPerRun: 20 });
  assert.deepEqual(p.send, [{ userId: "ok", productLabel: "VPS", amountCents: 900 }]);
  assert.equal(p.skipped.cooldown, 1);
  assert.equal(p.skipped.already_converted, 1);
  assert.equal(p.skipped.opted_out, 1);
  assert.equal(p.skipped.recent_winback, 1);
  const capped = planReminders({ items, users, now, cooldownDays: 14, maxAgeDays: 7, maxPerRun: 0 });
  assert.equal(capped.send.length, 0);
});

test("abandoned-checkout email: honest copy, unsubscribe, tracked CTA, no coupon", () => {
  const b = SAMPLES.abandonedCheckout();
  assert.equal(b.template, "abandoned_checkout");
  assert.ok(b.html.includes(SAMPLE_UNSUB));
  assert.ok(b.html.includes("utm_campaign=abandoned_checkout"));
  assert.ok(/nothing was charged/i.test(b.html));
  assert.ok(!/coupon|% off|discount/i.test(b.html));
});

test("server-step defaults are valid and editable", () => {
  assert.equal(defaultServerName("Minecraft"), "Minecraft server");
  assert.equal(defaultServerName(null), "My server");
  assert.ok(isDefaultServerName("", "Minecraft") && isDefaultServerName("Minecraft server", "Minecraft"));
  assert.ok(!isDefaultServerName("Bob's world", "Minecraft"));
  for (const name of ["Minecraft", "Counter-Strike 2", "7 Days to Die", "V Rising", "x", "Project Zomboid"]) {
    for (const r of [0, 0.5, 0.999]) {
      const s = suggestSubdomain(name, () => r);
      assert.ok(SUBDOMAIN_RE.test(s), `${name} -> ${s}`);
      assert.ok(!RESERVED_SUBDOMAINS.has(s));
    }
  }
});
