const ev = (p: Partial<FunnelEventRow>): FunnelEventRow => ({
  product: "game", step: "Game", stepIndex: 0, type: "step", errorCode: null, detail: null,
  sessionId: null, visitorId: null, userId: null, ...p,
});

test("funnel: step conversion, reasons, dwell, bot sessions dropped, completion matched by user", () => {
  const rows: FunnelEventRow[] = [];
  for (const s of ["s1", "s2", "s3", "bot1"]) rows.push(ev({ sessionId: s, step: "Game", stepIndex: 1 }));
  for (const s of ["s1", "s2", "bot1"]) rows.push(ev({ sessionId: s, step: "Server", stepIndex: 2 }));
  rows.push(ev({ sessionId: "s1", step: "Payment", stepIndex: 4, userId: "u1" }));
  rows.push(ev({ sessionId: "s1", step: "Payment", stepIndex: 4, userId: "u1", type: "payment", errorCode: "card_declined" }));
  rows.push(ev({ sessionId: "s2", step: "Server", stepIndex: 2, type: "payment", errorCode: "validation_error" }));
  rows.push(ev({ sessionId: "s1", step: "Server", stepIndex: 2, type: "dwell", detail: JSON.stringify({ ms: 4000 }) }));
  rows.push(ev({ sessionId: "s1", step: "Server", stepIndex: 2, type: "dwell", detail: JSON.stringify({ ms: 8000 }) }));
  // server-side completion: only userId + (stamped) session
  rows.push(ev({ sessionId: "s1", userId: "u1", type: "complete", step: "Complete", stepIndex: 5 }));
  const f = buildProductFunnel("game", rows, new Set(["bot1"]))!;
  assert.equal(f.botActorsExcluded, 1);
  assert.equal(f.started, 3);
  assert.equal(f.completed, 1);
  const game = f.steps.find((s) => s.step === "Game")!;
  assert.equal(game.reached, 3);
  assert.equal(game.continued, 2);
  assert.ok(Math.abs(game.conversionToNext - 2 / 3) < 1e-9);
  const server = f.steps.find((s) => s.step === "Server")!;
  assert.equal(server.reached, 2);
  assert.equal(server.continued, 1); // only s1 reaches Payment
  assert.deepEqual(server.reasons, [{ reason: "validation_error", actors: 1 }]);
  assert.equal(server.noReasonLogged, 0); // s2 left with a logged reason
  assert.equal(server.medianDwellMs, 6000);
  const pay = f.steps.find((s) => s.step === "Payment")!;
  assert.equal(pay.continued, 1); // completed
  assert.deepEqual(pay.reasons, [{ reason: "card_declined", actors: 1 }]);
});

