test("stale sweep: abandons unpaid, never a COMPLETED order, never a PAID row, skips on API error", async () => {
  const old = new Date(Date.now() - 46 * 86_400_000);
  const mk = (id: string, status: string, ref: string | null) => ({ id, provider: "paypal", kind: "gameOrder", userId: "u", amountCents: 1000, providerRef: ref, status, createdAt: old, updatedAt: old });
  pending.length = 0;
  pending.push(mk("a", "PENDING", "O-CREATED"), mk("b", "PENDING", "O-DONE"), mk("c", "PAID", "O-PAID"), mk("d", "PENDING", "O-ERR"), mk("e", "PENDING", null), mk("f", "PENDING", "O-404"));
  const seen: string[] = [];
  const r = await sweepStalePendingPayments(24, {
    getPayPalStatus: async (id) => {
      if (id === "O-CREATED") return "CREATED";
      if (id === "O-DONE") return "COMPLETED";
      if (id === "O-404") throw new Error("PayPal API /v2/checkout/orders/x failed: 404 {}");
      throw new Error("timeout");
    },
    onAbandoned: async (row) => { seen.push(row.id); },
  });
  const st = Object.fromEntries(pending.map((p) => [p.id, p.status]));
  assert.deepEqual(st, { a: "ABANDONED", b: "PENDING", c: "PAID", d: "PENDING", e: "ABANDONED", f: "ABANDONED" });
  assert.deepEqual(seen.sort(), ["a", "e", "f"]);
  assert.equal(r.paidUnfulfilled, 1);
  assert.equal(r.skipped, 1);
  assert.equal(r.abandoned, 3);
});

